package org.sleepwell.app;
import android.content.*;import android.database.sqlite.*;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public final class TagStorageTest {
 final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();
 final class Fixture implements AutoCloseable {final String name="tags-"+UUID.randomUUID()+".db";final Store store=new Store(c,name);final long now=System.currentTimeMillis(),end=now-86400000,start=end-8*3600000;long add(String name,double amount){RecordDraft draft=new RecordDraft(start,end);draft.note="Original notes";draft.addTag(name);if(amount>=0)draft.quantity(name,new TagQuantity(amount,"cups"));return Records.create(store,draft,java.time.ZoneId.of("UTC"),now);}public void close(){store.close();c.deleteDatabase(name);}}
 @Test public void quantityRoundTripCopiesAndBothCsvPathsPreserveTypedValue()throws Exception{try(Fixture f=new Fixture()){long id=f.add("Coffee",2.5);RecordEntry original=Records.get(f.store,id);assertEquals(new TagQuantity(2.5,"cups"),original.edit.quantities.get("Coffee"));assertEquals(original.edit.quantities,original.draft(original.edit.copy()).edit.quantities);assertEquals(Records.csv(f.store),new String(BackupDocuments.csv(f.store,()->true),java.nio.charset.StandardCharsets.UTF_8));try(Store reopened=new Store(c,f.name)){assertEquals(original.edit.quantities,Records.get(reopened,id).edit.quantities);}}}
 @Test public void portableBackupKeepsLegacyStringsAndQuantities()throws Exception{try(Fixture f=new Fixture();Fixture target=new Fixture()){f.add("Coffee",2);f.add("Exercise",-1);JSONObject backup=f.store.backup();Backup.restoreData(target.store,backup);assertEquals(2,Records.all(target.store).size());assertTrue(Records.all(target.store).stream().anyMatch(r->r.edit.quantities.get("Coffee")!=null));assertTrue(Records.all(target.store).stream().anyMatch(r->r.edit.tags.contains("Exercise")&&r.edit.quantities.isEmpty()));}}
 @Test public void renamePreservesQuantityRawRowsAndSourceEvidence()throws Exception{try(Fixture f=new Fixture()){long id=f.add("Coffee",2);HealthSleep remote=new HealthSleep("hc","com.provider.sleep",f.start-86400000,f.end-86400000,1,0,0,"HC","Source note",List.of());new HealthSleepStore(f.store).apply(List.of(remote),List.of(),"hc-token","org.sleepwell.app",f.now);RecordEntry imported=Records.all(f.store).stream().filter(r->!r.healthConnect.isEmpty()).findFirst().orElseThrow();RecordDraft importedDraft=imported.edit.copy();importedDraft.addTag("Coffee");importedDraft.quantity("Coffee",new TagQuantity(3,"cups"));Records.save(f.store,imported.id,importedDraft,imported.updated,f.now+1);List<JSONObject> raw=f.store.rows("SELECT * FROM sessions");String expected=TagRecords.signature(Records.all(f.store),"Coffee");assertEquals(2,TagRecords.change(f.store,"Coffee","Caffeine",expected,f.now+2));assertEquals(imported.healthConnect,Records.get(f.store,imported.id).healthConnect);assertEquals(new TagQuantity(3,"cups"),Records.get(f.store,imported.id).edit.quantities.get("Caffeine"));assertEquals(raw.toString(),f.store.rows("SELECT * FROM sessions").toString());RecordEntry changed=Records.get(f.store,id);assertEquals(List.of("Caffeine"),changed.edit.tags);assertEquals(new TagQuantity(2,"cups"),changed.edit.quantities.get("Caffeine"));assertEquals("Original notes",changed.edit.note);}}
 @Test public void concurrentEditOrNewTaggedRecordRejectsWholeMutation()throws Exception{try(Fixture f=new Fixture()){long id=f.add("Coffee",2);String expected=TagRecords.signature(Records.all(f.store),"Coffee");final String originalExpected=expected;RecordEntry entry=Records.get(f.store,id);RecordDraft edit=entry.edit.copy();edit.note="New local edit";Records.save(f.store,id,edit,entry.updated,f.now+1);String before=BackupFingerprint.read(f.store);assertThrows(IllegalStateException.class,()->TagRecords.change(f.store,"Coffee",null,originalExpected,f.now+2));assertEquals(before,BackupFingerprint.read(f.store));expected=TagRecords.signature(Records.all(f.store),"Coffee");f.add("Coffee",3);String stale=expected,after=BackupFingerprint.read(f.store);assertThrows(IllegalStateException.class,()->TagRecords.change(f.store,"Coffee","Caffeine",stale,f.now+3));assertEquals(after,BackupFingerprint.read(f.store));}}
 @Test public void collisionCannotDiscardAnExistingQuantity()throws Exception{try(Fixture f=new Fixture()){f.add("Coffee",2);f.add("Caffeine",3);String expected=TagRecords.signature(Records.all(f.store),"Coffee"),before=BackupFingerprint.read(f.store);assertThrows(IllegalArgumentException.class,()->TagRecords.change(f.store,"Coffee","caffeine",expected,f.now+1));assertEquals(before,BackupFingerprint.read(f.store));}}
 @Test public void globalDeleteRemovesOnlyTagAndQuantityAndKeepsOtherTags()throws Exception{try(Fixture f=new Fixture()){long id=f.add("Coffee",2);RecordEntry entry=Records.get(f.store,id);RecordDraft edit=entry.edit.copy();edit.addTag("Exercise");Records.save(f.store,id,edit,entry.updated,f.now+1);String expected=TagRecords.signature(Records.all(f.store),"coffee");TagRecords.change(f.store,"coffee",null,expected,f.now+2);RecordEntry result=Records.get(f.store,id);assertEquals(List.of("Exercise"),result.edit.tags);assertTrue(result.edit.quantities.isEmpty());assertEquals("Original notes",result.edit.note);}}
 @Test public void laterFailureRollsBackEarlierGlobalUpdates()throws Exception{try(Fixture f=new Fixture()){f.add("Coffee",2);long second=f.add("Coffee",3);String expected=TagRecords.signature(Records.all(f.store),"Coffee"),before=BackupFingerprint.read(f.store);f.store.getWritableDatabase().execSQL("CREATE TRIGGER fail_tag BEFORE INSERT ON record_edits WHEN NEW.session="+second+" BEGIN SELECT RAISE(ABORT,'Injected tag save failure'); END");assertThrows(SQLiteException.class,()->TagRecords.change(f.store,"Coffee","Caffeine",expected,f.now+1));assertEquals(before,BackupFingerprint.read(f.store));}}
 @Test public void strictMalformedQuantityImportFailsBeforeReplacement()throws Exception{try(Fixture f=new Fixture();Fixture target=new Fixture()){f.add("Coffee",2);JSONObject backup=f.store.backup();String before=BackupFingerprint.read(target.store);for(Object invalid:List.of("2",-1,1000001)){JSONObject copy=new JSONObject(backup.toString());JSONArray tags=new JSONArray(copy.getJSONArray("edits").getJSONObject(0).getString("tags"));tags.getJSONObject(0).put("quantity",invalid);copy.getJSONArray("edits").getJSONObject(0).put("tags",tags.toString());assertThrows(JSONException.class,()->Backup.restoreData(target.store,copy));assertEquals(before,BackupFingerprint.read(target.store));}}}
}
